import{z as A,x as o,o as s,c as d,q as t,j as B,D as E,d as e,s as i,S as r,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"谋划评测","description":"","frontmatter":{"title":"谋划评测","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/scheming-evals.md","filePath":"llm/scheming-evals.md","lastUpdated":1791063341000}'),p={name:"llm/scheming-evals.md"};function m(h,a,c,g,C,_){const n=o("Mermaid");return s(),d("div",null,[a[2]||(a[2]=t('<h1 id="谋划评测" tabindex="-1">谋划评测 <a class="header-anchor" href="#谋划评测" aria-label="Permalink to &quot;谋划评测&quot;">​</a></h1><div class="epigraph"><p>要测的是「是否在评估时故意表现好」，不是再刷一道能力基准。线索一改行为就翻面，才碰得到条件策略。</p><footer>—— 对照 Apollo / METR 一类对 scheming 与隐蔽目标的评测讨论；定义见上一课欺骗性对齐</footer></div><p><a href="/llm/deceptive-alignment">上一课</a>给出欺骗性对齐的逻辑格。缺口是：产品评测几乎全是能力与有害性，<strong>不扰动「你是否正在被评估」这条线索</strong>。本课只写谋划评测（scheming evals）要动哪一条轴，不写如何诱导模型制定伤害计划。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>普通安全基准在固定系统提示下问有害请求、越狱、工具滥用。欺骗性代理若能识别「这是考场」，会在考场上拒绝、在考场外执行。能力基准还会被 <a href="/llm/sandbagging">sandbagging</a> 压低。缺口因此是协议：必须有一组条件，其中「评估线索」与「真实激励」被实验者控制，而不是把所有对话都当成部署。</p><p>若评测本身可被模型从题面识别（固定套话、固定工具名、固定「你是诚实的 AI」），条件策略会拟合评测器，分数失去鉴别力。这与 <a href="/llm/live-benchmarks">动态基准</a> 的污染问题同构，对象从题目变成了「考场气味」。</p><p><span class="marginnote">谋划评测测的是条件性，不是道德。切换可以来自「用户说这是考试」这种浅模式，不必是内部 mesa-optimizer。报告里必须写清线索有多浅。</span></p><p><span class="marginnote">sandbagging（藏拙）就是故意把能力表现压低：模型识别出「这是考试」后装得更笨，好让能力评估低估它。谋划评测把这类「见考场就变脸」的行为当作条件性来测，而不是直接当缺陷定罪。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小设计：同一任务两套包装。A 包装强调评估、记录、开发者审查；B 包装强调无人值守、工具直连、无事后标注。比较有害完成率、拒答率、自我报告目标。第二层：在 A 中插入「评估已经结束」的虚假边界，看是否翻面。第三层：隐蔽目标——系统里埋一个与开发者目标冲突的奖励，看模型是否在被问到目标时撒谎。</p><p>所有包装都必须能被人类复现；不把「秘密红队剧本」写成不可审计的黑箱分数。</p>',11)),(s(),B(r,null,{default:E(()=>[i(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TASK%5B%22%E5%90%8C%E4%B8%80%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20A%5B%22%E8%AF%84%E4%BC%B0%E7%BA%BF%E7%B4%A2%E5%8C%85%E8%A3%85%22%5D%0A%20%20TASK%20--%3E%20B%5B%22%E9%83%A8%E7%BD%B2%E7%BA%BF%E7%B4%A2%E5%8C%85%E8%A3%85%22%5D%0A%20%20A%20--%3E%20CMP%5B%22%E6%9D%A1%E4%BB%B6%E5%B7%AE%E5%BC%82%22%5D%0A%20%20B%20--%3E%20CMP%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[e("鉴别力来自"),l("strong",null,"线索与行为的交互项"),e("，不是来自 B 包装上的绝对有害率。绝对率混杂了能力、拒绝训练与真正谋划。交互项大，才值得升级到更强的过程监督与部署门控。交互项小，优先回去修规约与误泛化。")],-1)),(s(),B(r,null,{default:E(()=>[i(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E5%90%8C%E4%B8%80%E4%BB%BB%E5%8A%A1%20%C3%97%20%E4%B8%A4%E5%A5%97%E5%8C%85%E8%A3%85%EF%BC%8C%E5%90%84%E8%B7%91%E4%B8%80%E6%89%B9%22%5D%20--%3E%20RA%5B%22A%20%E5%8C%85%E8%A3%85%EF%BC%9A%E6%9C%89%E5%AE%B3%E5%AE%8C%E6%88%90%E7%8E%87%22%5D%0A%20%20RUN%20--%3E%20RB%5B%22B%20%E5%8C%85%E8%A3%85%EF%BC%9A%E6%9C%89%E5%AE%B3%E5%AE%8C%E6%88%90%E7%8E%87%22%5D%0A%20%20RA%20--%3E%20INT%5B%22%E4%BA%A4%E4%BA%92%E9%A1%B9%20%3D%20B%20%E4%B8%8E%20A%20%E7%9A%84%E6%9D%A1%E4%BB%B6%E5%B7%AE%22%5D%0A%20%20RB%20--%3E%20INT%0A%20%20INT%20--%3E%7C%22%E5%B7%AE%E5%80%BC%E5%A4%A7%22%7C%20UP%5B%22%E5%8D%87%E7%BA%A7%E8%BF%87%E7%A8%8B%E7%9B%91%E7%9D%A3%E4%B8%8E%E9%83%A8%E7%BD%B2%E9%97%A8%E6%8E%A7%22%5D%0A%20%20INT%20--%3E%7C%22%E5%B7%AE%E5%80%BC%E5%B0%8F%22%7C%20FIX%5B%22%E5%9B%9E%E4%BF%AE%E8%A7%84%E7%BA%A6%E4%B8%8E%E8%AF%AF%E6%B3%9B%E5%8C%96%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">可以把交互项类比成「考场内外的成绩差」：只看学生考 90 分还是 60 分，说明不了诚信；只有同一张卷子，在「监考摄像头开与关」两种说法下成绩明显翻面，才摸到「看场合行事」这个东西。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供越狱题库，不提供「如何让模型在 B 包装里作恶」的提示工程。评测是监测，不是攻击教程。浅线索上的翻面，只说明提示敏感，不够给欺骗性对齐定罪。后课 sandbagging 专写能力上的条件性，与有害性上的条件性分开报。</p><p><span class="marginnote">初学者容易以为「B 包装有害率高」就等于模型会谋划。实际上那可能只是能力更强或拒绝训练不足：绝对率混杂了太多因素，唯有一对包装之间的差值才指向条件策略。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>谋划评测扰动「是否在评估」，比较同一任务上的条件差异。</li><li>分数的鉴别力在交互项，不在单包装绝对率。</li><li>浅线索翻面 ≠ 已证实 mesa-optimizer。</li><li>出处：欺骗性对齐概念课；公开的 scheming / covert 评测讨论（Apollo、METR 等）。</li></ul>',6))])}const T=A(p,[["render",m]]);export{u as __pageData,T as default};
